# Dynamic Image Finder
def find_gorsel_path(file_path):
    if not file_path:
        return None
    file_name = os.path.basename(file_path)
    base_name, _ = os.path.splitext(file_name)
    possible_dirs = [".", "gorseller", "/workspace/artifacts", "/workspace/knowledge"]
    possible_exts = [".jpg", ".jpeg", ".png", ".PNG", ".JPG"]
    
    for d in possible_dirs:
        for ext in possible_exts:
            candidate = os.path.join(d, base_name + ext)
            if os.path.exists(candidate):
                return candidate
    return None

