            st.markdown("#### 🔬 PATOFİZYOLOJİ")
            st.write(eg.get("patofizyoloji", "-"))
            
            st.markdown("#### ⚖️ AYIRICI TANI KRİTERLERİ")
            st.write(eg.get("ayirici_tani", "-"))
            
            st.markdown("#### 💊 TEDAVİ & SAĞALTIM PROTOKOLÜ")
            st.write(eg.get("tedavi", "-"))
            
            st.markdown("#### 🛡️ BİYOGÜVENLİK & KORUMA")
            st.write(eg.get("biyoguvenlik", "-"))
            
            st.markdown("---")
            st.markdown("#### 🔑 Bu Vakanın Gizli Tüm Kategori Bilgileri:")
            for ck, cv in active_case["categories"].items():
                st.markdown(f"**• {cv['name']}:** {cv['content']}")
